script:
frappe.ui.form.on("Driver", {
	refresh(frm) {
		if (frm.is_new()) {
			return;
		}

		if (!frm.doc.is_blacklisted) {
			frm.add_custom_button(__("Blacklist Driver"), () => {
				frappe.prompt(
					{ fieldname: "reason", fieldtype: "Small Text", label: __("Reason"), reqd: 1 },
					(values) => {
						frappe.call({
							method: "transport.transport.doctype.driver_incident.driver_incident.set_driver_blacklist",
							args: { driver: frm.doc.name, blacklisted: 1, reason: values.reason },
							callback: () => frm.reload_doc(),
						});
					},
					__("Blacklist Driver")
				);
			}, __("Transport"));
		} else {
			frm.add_custom_button(__("Clear Blacklist"), () => {
				frappe.call({
					method: "transport.transport.doctype.driver_incident.driver_incident.set_driver_blacklist",
					args: { driver: frm.doc.name, blacklisted: 0 },
					callback: () => frm.reload_doc(),
				});
			}, __("Transport"));
		}
	},
});

frappe.ui.form.on("Sales Invoice", {
	refresh(frm) {
		if (frm.is_new() || !frm.doc.transport_timesheet) {
			return;
		}

		if (frm.doc.grn_status === "Pending") {
			frm.add_custom_button(__("Mark GRN Received"), () => {
				frappe.call({
					method: "transport.transport.billing.mark_grn_received",
					args: { sales_invoice: frm.doc.name },
					callback: () => frm.reload_doc(),
				});
			}, __("Transport"));
		}

		if (frm.doc.grn_status === "Received" && frm.doc.invoice_submission_status === "Not Submitted") {
			frm.add_custom_button(__("Mark Invoice Submitted"), () => {
				frappe.call({
					method: "transport.transport.billing.mark_invoice_submitted",
					args: { sales_invoice: frm.doc.name },
					callback: () => frm.reload_doc(),
				});
			}, __("Transport"));
		}

		if (frm.doc.certificate_of_completion) {
			frm.add_custom_button(__("Certificate of Completion"), () => {
				frappe.set_route("Form", "Certificate of Completion", frm.doc.certificate_of_completion);
			}, __("Transport"));
		}
	},
});

frappe.listview_settings['Rental Vehicle'] = {
	onload(listview) {
		listview.page.add_actions_menu_item(__('Fetch Fines'), () => {
			const vehicles = listview.get_checked_items(true);
			if (!vehicles.length) {
				frappe.msgprint(__('Select at least one vehicle.'));
				return;
			}

			frappe.confirm(
				__('Fetch traffic fines for {0} selected vehicle(s)?', [vehicles.length]),
				() => {
					frappe.dom.freeze(__('Fetching fines...'));
					frappe.call({
						method: 'transport.transport.fine_sync.service.fetch_fines_for_vehicles',
						args: { vehicles: vehicles },
					}).then((r) => {
						frappe.dom.unfreeze();
						if (!r.message) return;
						const d = r.message;

						let html = `<p>${__('Vehicles selected')}: <b>${d.vehicles}</b><br>
							${__('Fines staged for review')}: <b>${d.fines_staged}</b></p>`;

						html += d.portals_queried.length
							? `<p>${__('Queried')}: ${d.portals_queried.map(frappe.utils.escape_html).join(', ')}</p>`
							: `<p>${__('No portal could be queried automatically.')}</p>`;

						// Coverage is stated plainly: a partial fetch must never
						// read as a complete picture of what a vehicle owes.
						if (d.coverage_note) {
							html += `<div class="alert alert-warning" style="margin-top:8px">
								<b>${__('Not a complete picture')}</b><br>${d.coverage_note}</div>`;
						}

						if (d.pending_operator && d.pending_operator.length) {
							html += `<p style="margin-top:8px"><b>${__('Still needs a person')}:</b></p><ul>`;
							d.pending_operator.forEach((p) => {
								html += `<li>${frappe.utils.escape_html(p.portal)}<br>
									<span class="text-muted small">${frappe.utils.escape_html((p.reason || '').slice(0, 220))}</span></li>`;
							});
							html += '</ul>';
						}

						if (d.fines_staged) {
							html += `<p style="margin-top:8px">
								<a href="/app/traffic-fine-staging?status=New">${__('Review staged fines')}</a></p>`;
						}

						frappe.msgprint({
							title: __('Fetch Fines'),
							indicator: d.police_fines_covered ? 'green' : 'orange',
							message: html,
						});
					}).catch(() => frappe.dom.unfreeze());
				}
			);
		});
	},
};
